func dump_connections(label: String) -> void:
	print("CONNECTION SNAPSHOT ", label, " orphans=", Performance.get_monitor(Performance.OBJECT_ORPHAN_NODE_COUNT))
	for sig in ["focus_entered", "tree_exited"]:
		for con in get_tree().root.get_signal_connection_list(sig):
			var c: Callable = con.callable
			var obj = c.get_object()
			print("CONNECTION ", sig, " id=", c.get_object_id(), " method=", c.get_method(), " object=", obj, " path=", obj.get_path() if obj is Node and obj.is_inside_tree() else "outside tree")
